const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const name = String(body.name ?? '').trim();
if (!name) {
  throw new Error('name is required');
}

const speciesLabel = String(body.speciesLabel ?? body.speciesSlug ?? 'pet').trim();
const speciesSlug = String(body.speciesSlug ?? '').trim();
const breedLabel = body.breedLabel ? String(body.breedLabel).trim() : null;
const sex = ['male', 'female', 'unknown'].includes(body.sex) ? body.sex : 'unknown';
const description = body.description ? String(body.description).trim().slice(0, 500) : null;
const dateOfBirth = body.dateOfBirth ? String(body.dateOfBirth).trim() : null;
const ageYears =
  typeof body.ageYears === 'number' && Number.isFinite(body.ageYears)
    ? body.ageYears
    : null;

const facts = {
  name,
  speciesLabel,
  speciesSlug,
  breedLabel,
  sex,
  description,
  dateOfBirth,
  ageYears,
};

const system =
  'You write short first-person greetings as a pet on Petsbook, a pet social network.\n' +
  'Produce TWO independent greetings (not a translation of each other): one English, one French (natural Canadian/European French).\n' +
  'Rules:\n' +
  '- Never mention AI, language models, prompts, or being artificial.\n' +
  '- Speak as the pet (I / me / je / moi).\n' +
  '- Each greeting: 2–3 short sentences, under 450 characters.\n' +
  '- Warm and natural; not corporate or salesy.\n' +
  '- Use only the provided facts. Do not invent awards, medical history, or other pets.\n' +
  '- Return ONLY valid JSON with exactly these keys (no markdown):\n' +
  '{"greeting":"<English greeting>","greetingFr":"<French greeting>"}';

const openAiBody = {
  model: 'gpt-4o-mini',
  temperature: 0.85,
  max_tokens: 450,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: system },
    {
      role: 'user',
      content: 'Write both greetings from these facts (JSON):\n' + JSON.stringify(facts, null, 2),
    },
  ],
};

return [{ json: { facts, openAiBody } }];

const content = String(
  $input.first().json.choices?.[0]?.message?.content ?? '',
)
  .trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '');

if (!content) {
  throw new Error('OpenAI returned empty greeting payload');
}

let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  throw new Error('OpenAI returned non-JSON greeting payload');
}

function clean(value) {
  return String(value ?? '')
    .trim()
    .replace(/^[\"'«»]+|[\"'«»]+$/g, '');
}

const greetingEn = clean(parsed.greeting ?? parsed.greetingEn);
const greetingFr = clean(parsed.greetingFr);

if (!greetingEn || !greetingFr) {
  throw new Error('OpenAI JSON missing greeting / greetingFr');
}

const max = 500;
function clip(text) {
  return text.length <= max ? text : `${text.slice(0, max - 1).trimEnd()}…`;
}

return [{ json: { greeting: clip(greetingEn), greetingFr: clip(greetingFr) } }];
